UPDATE courses SET
    course_description = '<h4>Course Description</h4><p>Learn the fundamentals of good design as you utilise your creativity and love of design and construction to create your own (virtual) building design projects. </p><p>This course is highly regarded by industry. It provides the practical skills, knowledge and qualifications to work as a building designer. You will gain specialist design skills applicable to residential and commercial design within the building design sector in a project-based setting, reflective of real office practice. Importantly, our strong industry partnerships allow students to work on live projects and graduate work-ready. </p><p>There are also opportunities to pursue further studies with pathways to university, where this course will provide you excellent grounding to take your studies further into Architecture and/or Building. </p><h5>Possible career outcomes</h5><ul><li>Building designers</li> <li>Architectural assistants </li> <li>Building design assistants </li> <li>Architectural draftspersons </li></ul>',
    total_course_duration = 'Full-time: 2 years',
    offshore_tuition_fee = 26000,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 860,
