UPDATE courses SET
    course_description = '<h4>Course Description</h4><p>Support your community and people experiencing hardship as you develop the knowledge needed for a rewarding career in the diverse community services industry. </p><p>The Diploma of Community Services course will build your leadership capabilities and give you the specialised skills you need to work in the community services sector, supporting the wellbeing of individuals, families and communities and helping to facilitate social change. </p><p>You’ll be qualified to manage a range of responsibilities while supporting people who are disadvantaged and vulnerable. If you''re driven to empower diverse communities, passionate about social justice and want to challenge the social structures that maintain disadvantage, then this qualification can help you achieve your goals. </p><p>Community Services workers empower and support disadvantaged and vulnerable people to achieve their goals. They provide housing, mental health, disability, multicultural, financial, youth, domestic and family violence support. Your experience and career goals will help determine your pathway.</p>',
    total_course_duration = 'Full-time: 15 months',
    offshore_tuition_fee = 13500,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 1030,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic:</h5><p>Successful completion of Australian Year 12 or equivalent – Equivalents can be found on our <a href="/international/helpful-information/country-equivalencies">Entry Requirements</a> page.</p><h5>English:</h5><p>IELTS Academic overall score of 6.0 with no band below 5.5 (or equivalent); or completion of Australian Year 12; or a qualification undertaken in Australia at Certificate IV or higher and completed within the past 5 years; or University studies in Australia of at least 2 years duration.</p><h5>Age/other requirements:</h5><p>You must be aged 18 years or over at the time of course commencement.</p><h5>Personal Learning Requirements</h5><p>There are personal learning requirements for each qualification at The Gordon. These are essential personal capabilities and skills required to successfully complete the course and be ready to work in the industry.</p><p><a href="/getmedia/9b42441e-5bf2-4ceb-b0c9-8c332a064240/CHC52025-Diploma-of-Community-Services-PLR.pdf">Please review the requirements here</a> and consider any challenges you may have in meeting them. When applying for your course, please let us know what support you may need. </p>',
    apply_form = 'https://www.thegordon.edu.au/international/international-courses/chc52025-diploma-of-community-services',
    updated_at = NOW()
WHERE cricos_course_code = '118872E';

UPDATE courses SET
    course_description = '<h4>Course Description</h4><p>This popular course will equip you with the knowledge and practical skills you need to register as an enrolled nurse or create a pathway to university. <br/><br/>Our experienced team of trainers will teach you about anatomy and physiology, communication skills, medical terminology, infection control, legal and ethical issues associated with nursing, nursing patients with complex needs, administering medications, and nursing patients with mental health needs. Our partnerships with Barwon Health, St John of God Hospital, and other healthcare providers also provide excellent work placement and employment opportunities. <br/><br/>This course is accredited by the Nursing and Midwifery Board of Australia (NMBA). Upon completing your studies, you will be eligible to register as an enrolled nurse with the NMBA.</p>',
    total_course_duration = 'Full-time: 2 Years',
    offshore_tuition_fee = 43000,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
