UPDATE courses SET
    course_description = '<h4>Course Description</h4><p>Are you an experienced industry professional looking for more than a standard cook’s qualification or dreaming of managing a professional kitchen? This course will equip you with the skills for both! </p><p>You will learn all facets of organising a professional kitchen, including selection, preparation, executing and cooking different menus and techniques. You will cover hygiene and safety procedures, staffing, environmental considerations, seasonal produce, quality control, stock control, bulk cooking, catering revenue and costs, finance, leadership, management and human resources. You will also have the opportunity to practice the skills learnt to run a series of live events both on campus and externally. You will take part in local foraging excursions, meet with primary producers and local business owners and learn from our highly skilled industry professionals. </p>',
    total_course_duration = 'Full-time: 6 months with current Certificate III in Commercial Cookery',
    offshore_tuition_fee = 8400,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 1220,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic:</h5><p>Applicants must have completed the SIT30821 Certificate III in Commercial Cookery.</p><h5>English:</h5><p>IELTS Academic overall score of 6.0 with no band below 5.5 (or equivalent) – Equivalents can be found on our <a href="/international/helpful-information/el-equivalency">English language equivalency</a> page.</p><h5>Other requirements:</h5><p>Applicants applying on a basis of entry other than successful completion of Certificate III in Commercial Cookery from The Gordon may be required to complete one or more prerequisite units which will incur extra unit tuition fee. Further information is provided at the time of enrolment.</p><h5>Personal Learning Requirements</h5><p>There are personal learning requirements for each qualification at The Gordon. These are essential personal capabilities and skills required to successfully complete the course and be ready to work in the industry.</p><p><a href="/getmedia/02069676-612e-4b1c-be36-183801fe4f42/SIT40521-Certificate-IV-in-Kitchen-Management.pdf">Please review the requirements here</a> and consider any challenges you may have in meeting them. When applying for your course, please let us know what support you may need. </p>',
    apply_form = 'https://www.thegordon.edu.au/international/international-courses/sit40521-certificate-iv-in-kitchen-management',
    updated_at = NOW()
WHERE cricos_course_code = '109624G';

UPDATE courses SET
    course_description = '<h4>Course Description</h4><p>If you love working with people and are looking for a rewarding career in the hospitality industry, then this course is for you!</p><p>You will learn to develop quality customer service skills, manage finances within a budget, and manage staff and regulatory requirements. The learning style combines hands-on and theory, teaching you everything you need to become a highly skilled manager in the hospitality industry.</p><h5>How often do I attend?</h5><p>Full time - 3 days a week</p>',
    total_course_duration = 'Full-time: 6 Months',
    offshore_tuition_fee = 7350,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 480,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic:</h5><p>Pre requisite courses - successfully completed:</p><ul><li>SIT30821 Certificate III in Commercial Cookery (1 year)</li><li>SIT40521 Certificate IV in Kitchen Management (6 months)</li></ul><h5>English:</h5><p>IELTS Academic overall score of 6.0 with no band below 5.5 (or equivalent) – Equivalents can be found on our <a href="/international/helpful-information/el-equivalency">English language equivalency</a> page.</p><h5>Age/other requirements:</h5><ul><li>You must be 18 years or over at the time of course commencement.</li><li>Applicants applying on a basis of entry other than successful completion of Certificate III in Commercial Cookery and Certificate IV in Kitchen Management from The Gordon may be required to complete one or more prerequisite units which will incur extra unit tuition fee. Further information is provided at the time of enrolment.</li></ul><h5>Personal Learning Requirements</h5><p>There are personal learning requirements for each qualification at The Gordon. These are essential personal capabilities and skills required to successfully complete the course and be ready to work in the industry.</p><p><a href="/getmedia/3a32f2b1-ffe2-4dcf-8a18-73a80894b05f/SIT50422-Diploma-of-Hospitality-Management.pdf">Please review the requirements here</a> and consider any challenges you may have in meeting them. When applying for your course, please let us know what support you may need. </p>',
    apply_form = 'https://www.thegordon.edu.au/international/international-courses/sit50422-diploma-of-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '113590M';

